export const medicationDefaults={
 m1:{ingredient:'Levothyroxine',start:'2024-01-12',end:null,issueStatus:'Issued',issuedAt:'2026-10-01',prescriber:'Dr. Nina Kovač',medicineType:'Thyroid hormone',caution:'Dose monitoring',catalog:'levothyroxine'},
 m2:{ingredient:'Colecalciferol',start:'2026-09-01',end:'2026-10-31',issueStatus:'Not recorded',issuedAt:null,prescriber:'Recorded supplement',medicineType:'Vitamin supplement',caution:'Supplement review',catalog:'colecalciferol'},
 m3:{ingredient:'Amlodipine',start:'2022-03-15',end:null,issueStatus:'Issued',issuedAt:'2026-10-01',prescriber:'Dr. Nina Kovač',medicineType:'Blood pressure medicine',caution:'Clinical monitoring',catalog:'amlodipine'},
 m4:{id:'m4',name:'Ibuprofen',dose:'400 mg',when:'Planned short course · sample prescription',ingredient:'Ibuprofen',start:'2026-10-17',end:'2026-10-21',issueStatus:'Not issued',issuedAt:null,prescriber:'Dr. Nina Kovač',medicineType:'NSAID painkiller',caution:'Additional precautions',catalog:'ibuprofen'}
};
export const medicineReferences={
 levothyroxine:{url:'https://www.nhs.uk/medicines/levothyroxine/',source:'NHS · Levothyroxine',risk:'The dose needs monitoring. Incorrect dosing can cause side effects.',interactions:[{names:'Calcium or iron supplements',detail:'Listed as medicines that may interact; professional review is needed.'},{names:'Antacids and omeprazole',detail:'May affect treatment; review the complete medicine list.'},{names:'Digoxin, some beta blockers and sertraline',detail:'Potential interactions requiring clinical review.'}]},
 colecalciferol:{url:'https://www.nhs.uk/medicines/colecalciferol/taking-colecalciferol-with-other-medicines-and-herbal-supplements/',source:'NHS · Colecalciferol interactions',risk:'Review other calcium or vitamin D products to avoid duplicate supplementation.',interactions:[{names:'Digoxin',detail:'Raised calcium may increase the risk of abnormal heart rhythm.'},{names:'Indapamide or bendroflumethiazide',detail:'May increase calcium in the blood.'},{names:'Other calcium or vitamin D supplements',detail:'Combined supplements require professional review.'}]},
 amlodipine:{url:'https://www.nhs.uk/medicines/amlodipine/',source:'NHS · Amlodipine',risk:'Dizziness and low blood pressure are considerations for clinical review.',interactions:[{names:'Simvastatin',detail:'A listed interaction; review the prescribed combination.'},{names:'Rifampicin or fluconazole',detail:'These medicines may affect amlodipine treatment.'},{names:'Other blood pressure medicines',detail:'The combined effects need professional review.'}]},
 ibuprofen:{url:'https://www.nhs.uk/medicines/ibuprofen-for-adults/',source:'NHS · Ibuprofen for adults',risk:'NSAID painkiller. Important risks include stomach ulceration or bleeding and kidney problems; risk increases with higher doses or longer use.',interactions:[{names:'Naproxen, aspirin and other NSAIDs',detail:'Combining NSAIDs increases the risk of serious side effects, including stomach ulcers.'},{names:'Warfarin and other anticoagulants',detail:'Potential interaction; professional review is required.'},{names:'Steroids, some antidepressants and blood pressure medicines',detail:'Potential interactions to review before prescribing.'}]}
};
export function medicationDate(date){return date?new Date(date.length===10?date+'T12:00:00':date).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'Europe/Ljubljana'}):'Not recorded';}
export function medicineLinkHTML(m,person,{icon,escapeHTML:e}){return `<button class="medicine-link" data-action="medicine" data-id="${e(m.id)}" data-patient="${e(person)}">${icon('pill')}<span>${e(m.name)} · ${e(m.dose)}</span>${icon('chevron')}</button>`;}
export function medicineTimelineHTML(m,{icon,escapeHTML:e}){return `<div class="medicine-timeline" aria-label="Treatment dates for ${e(m.name)}"><div><span class="timeline-point"></span><small>Start date</small><strong>${medicationDate(m.start)}</strong></div><div class="medicine-timeline-line" aria-hidden="true"></div><div><span class="timeline-point ${!m.end?'ongoing':''}"></span><small>${m.end?'End date':'End date'}</small><strong>${m.end?medicationDate(m.end):'Ongoing · not set'}</strong></div></div>`;}
export function medicineRowHTML(m,person,{icon,escapeHTML:e},staff=false){return `<div class="medicine-record ${m.catalog==='ibuprofen'?'medicine-caution':''}">${staff?medicineLinkHTML(m,person,{icon,escapeHTML:e}):`<strong>${e(m.name)} · ${e(m.dose)}</strong>`}<div class="medicine-tags"><span class="pill ${m.issueStatus==='Issued'?'':'amber'}">${e(m.issueStatus==='Issued'?'Issued · demo':m.issueStatus==='Not issued'?'Not issued':'Issue status not recorded')}</span>${m.catalog==='ibuprofen'?`<span class="pill amber">${icon('alert')} Painkiller · extra precautions</span>`:''}</div><p class="small muted">${e(m.when)}</p><p class="medicine-dates">${medicationDate(m.start)} → ${m.end?medicationDate(m.end):'Ongoing'}</p></div>`;}
export function medicationDetailHTML(m,p,{icon,escapeHTML:e}){const reference=medicineReferences[m.catalog];return `<p class="eyebrow">${e(p.name)} · SAMPLE MEDICATION RECORD</p><div class="medication-spec"><div><span>Active ingredient</span><strong>${e(m.ingredient||'Not recorded')}</strong></div><div><span>Medicine type</span><strong>${e(m.medicineType||'Not recorded')}</strong></div><div><span>Prescription status</span><strong>${e(m.issueStatus==='Issued'?'Issued in this demo':m.issueStatus)}</strong></div><div><span>Issue date</span><strong>${medicationDate(m.issuedAt)}</strong></div><div><span>Recorded strength</span><strong>${e(m.dose)}</strong></div><div><span>Prescriber / source</span><strong>${e(m.prescriber||'Not recorded')}</strong></div></div><h3 class="section-label">Medication treatment timeline</h3>${medicineTimelineHTML(m,{icon,escapeHTML:e})}<p class="small muted">${m.issueStatus==='Not issued'?'Planned dates; the prescription has not been issued.':'Recorded treatment period; actual dose-taking is not confirmed.'} Dates are fictional.</p><div class="notice ${m.catalog==='ibuprofen'?'warning':''}" style="margin-top:20px">${icon('alert')}<span><strong>${e(m.caution||'Medication precautions')}</strong><br>${e(reference?.risk||'Clinical information is not available in this demo.')}</span></div><h3 class="section-label">Incompatible / interacting medicines</h3><p class="small muted">Examples to review, not a complete compatibility check. Some combinations require monitoring rather than being absolutely prohibited.</p><div class="interaction-list">${reference?reference.interactions.map(i=>`<div class="interaction-row">${icon('alert')}<div><strong>${e(i.names)}</strong><p>${e(i.detail)}</p></div></div>`).join(''):'<p>No reference data loaded. This does not establish compatibility.</p>'}</div>${reference?`<p class="reference-link">Reference: <a href="${reference.url}" target="_blank" rel="noopener noreferrer">${e(reference.source)} ${icon('arrow')}</a></p>`:''}<p class="warning-note">Reference examples only. The demo does not screen the patient’s full medication list or authorize treatment changes.</p>`;}
